"""The Coding Learning Foundation curriculum: kindergarten through a computer science degree to a software engineering job.
K-12 courses are reused from the Med School Learning Foundation (same lessons), with coding-oriented notes.
Writes work/courses_raw.json (writer-facing) and work/meta.json (site-facing extras)."""
import json, copy

MED_RAW = {c['code']: c for c in json.load(open('/home/claude/med/work/courses_raw.json'))}

STAGES = [
    ('K', 'Elementary school (K–5)', 'Numbers, reading and writing, science and the world around us, plus first steps in computational thinking and Python, learned with a grown-up close by.'),
    ('J', 'Middle school (6–8)', 'Ratios to algebra, reading and writing, the sciences and history, plus programming in Python and how computers and the internet work.'),
    ('H', 'High school (9–12)', 'Algebra through calculus and statistics, the lab sciences, English and history, plus Python with data and algorithms, and object-oriented programming.'),
    ('C', 'College computer science', 'The core of a computer science degree: programming, discrete math, tools, data structures, algorithms, systems, networks, databases, theory, languages, software engineering, the mathematics of computing, security, AI, machine learning, the web and distributed systems.'),
    ('P', 'Software engineering career', 'Testing and code quality, design and architecture, system design, interview preparation, a shipped capstone project, and professional practice.'),
]
LEVEL = {'K': 'elementary', 'J': 'middle', 'H': 'high', 'C': 'college', 'P': 'professional'}
FINAL_MIN = {'elementary': 30, 'middle': 45, 'high': 60, 'college': 120, 'professional': 120}
HOURS = {'elementary': '2–3', 'middle': '3–4', 'high': '4–6', 'college': '8–12', 'professional': '8–12'}

COURSES = []

def C(code, title, profile, req, soft, purpose, why, ready, reading, units, project, elective=False):
    assert len(units) == 6, code
    assert 'Week 7 midterm' in units[3][2], code
    lvl = LEVEL[code[0]]
    fm = FINAL_MIN[lvl]
    u = []
    for i, (a, b, d) in enumerate(units):
        u.append({'weeks': [2 * i + 1, 2 * i + 2], 'topics': [a, b], 'deliverable': d})
    u.append({'weeks': [13, 14], 'topics': ['Project and review', 'Cumulative final'],
              'deliverable': f'Submit the project; take an unseen {fm} minute final in week 14.'})
    completion = 'finish the project, take the week 7 midterm and week 14 cumulative final, then complete a new cumulative assessment after 1 to 2 weeks. Explain one major idea aloud without notes.'
    COURSES.append({'code': code, 'title': title, 'stage': code[0], 'level': lvl, 'profile': profile, 'req': req, 'soft': soft,
                    'prerequisites': (', '.join(req) if req else 'None') + ('; helpful: ' + ', '.join(soft) if soft else '') + '.',
                    'purpose': purpose, 'why': why, 'ready': ready,
                    'reading': {'title': reading[0], 'url': reading[1]}, 'readingScope': None, 'readingNote': None,
                    'units': u, 'project': project, 'completion': completion, 'supplement': None, 'elective': elective})

# ---------------- K-12: reused from the Med School Learning Foundation ----------------
WHY = {
    'K1': 'Counting and number sense are the base of every calculation a program does.',
    'K2': 'Place value and multiplication are the ideas behind binary numbers and loops.',
    'K3': 'Fractions, decimals and multi-step arithmetic come back in every program that computes.',
    'K4': 'Reading is how you will learn everything else on this path, including code and its documentation.',
    'K5': 'Fluent reading and clear writing make error messages, documentation and later textbooks easy.',
    'K6': 'Research and clear explanations grow into reading documentation and writing about code.',
    'K7': 'Observing carefully and describing exactly what you see is where debugging begins.',
    'K8': 'Science teaches you to test an idea with an experiment, the same habit as testing code.',
    'K9': 'Communities, maps and history are the world of the people who use software.',
    'J1': 'Ratios, rates and negative numbers appear in every program that measures or scales.',
    'J2': 'Equations and probability underlie algorithms, games and simulations.',
    'J3': 'Functions in mathematics are the model for functions in code.',
    'J4': 'Programmers read requirements closely and explain their work in writing every day.',
    'J5': 'Living systems supply data and models that programs simulate, from genes to ecosystems.',
    'J6': 'Electricity, motion and energy explain the hardware that runs code and the physics in games.',
    'J7': 'Earth and space science supply real data sets and simulations to program.',
    'J8': 'History explains how technology and the societies that use it developed.',
    'H1': 'Algebra and functions are the everyday mathematics of programming.',
    'H2': 'Geometric proof trains the step-by-step reasoning used to prove programs correct, and coordinates underlie graphics.',
    'H3': 'Trigonometry and vectors are the mathematics of graphics, games and robotics.',
    'H4': 'Exponential and logarithmic functions describe how algorithms and data grow.',
    'H5': 'Calculus is required for a computer science degree and underlies optimization and machine learning.',
    'H6': 'Statistics and probability are the basis of data science, experiments and machine learning.',
    'H7': 'Biology is a science that computing increasingly drives, from genomics to medicine.',
    'H8': 'Chemistry rounds out the lab sciences that most high schools and many CS degrees expect.',
    'H9': 'Physics explains the hardware of computers and the simulations in games and engineering.',
    'H10': 'Close reading and clear writing prepare you to understand specifications and write documentation.',
    'H11': 'Research and professional writing are daily tools for design documents, reports and proposals.',
    'H12': 'U.S. history and government give context for technology policy, privacy and the law.',
    'H13': 'World history and geography give context for a global industry and its users.',
}
for code, why in WHY.items():
    t = copy.deepcopy(MED_RAW[code])
    t['why'] = why
    t['reusedFrom'] = 'med:' + code
    t['elective'] = False
    COURSES.append(t)

OCW = 'https://ocw.mit.edu/courses/'

